ALTER TABLE public.workforce_schedules ADD COLUMN allowed_methods text[] NOT NULL DEFAULT ARRAY['account','pin','voice'];
CREATE FUNCTION public.employee_clock_configuration(_employee uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'attendance') OR public.employee_org_id(_employee) IS DISTINCT FROM public.current_org_id() THEN RAISE EXCEPTION 'Company attendance manager required'; END IF; SELECT to_jsonb(s)||jsonb_build_object('employee_code',c.employee_code,'pin_configured',c.pin_hash IS NOT NULL) INTO result FROM public.workforce_schedules s LEFT JOIN public.workforce_clock_credentials c ON c.employee_id=s.employee_id AND c.org_id=s.org_id WHERE s.employee_id=_employee AND s.org_id=public.current_org_id(); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.employee_clock_configuration(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.employee_clock_configuration(uuid) TO authenticated;
CREATE FUNCTION public.configure_employee_clock_methods(_employee uuid,_code text,_pin text,_start time,_end time,_days integer[],_break integer,_site uuid,_enabled boolean,_methods text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF _methods IS NULL OR cardinality(_methods)=0 OR NOT _methods<@ARRAY['account','pin','voice'] OR array_position(_methods,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Choose at least one clock method'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_employee) AND NOT ('pin'=ANY(_methods)) THEN RAISE EXCEPTION 'Employees without a sign-in account need PIN clock access'; END IF;
IF 'pin'=ANY(_methods) AND _pin IS NULL AND NOT EXISTS(SELECT 1 FROM public.workforce_clock_credentials WHERE employee_id=_employee AND org_id=public.current_org_id()) THEN RAISE EXCEPTION 'Assign a PIN for PIN clock access'; END IF;
PERFORM public.configure_employee_clock(_employee,_code,_pin,_start,_end,_days,_break,_site,_enabled);
UPDATE public.workforce_schedules SET allowed_methods=_methods WHERE employee_id=_employee AND org_id=public.current_org_id();
END $$;
REVOKE ALL ON FUNCTION public.configure_employee_clock_methods(uuid,text,text,time,time,integer[],integer,uuid,boolean,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.configure_employee_clock_methods(uuid,text,text,time,time,integer[],integer,uuid,boolean,text[]) TO authenticated;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.record_workforce_punch(uuid,uuid,text,text,double precision,double precision)'::regprocedure) INTO definition; definition:=replace(definition,'IF sc.site_id IS NOT NULL THEN','IF sc.id IS NULL OR NOT (CASE WHEN _mode=''device'' THEN ''account'' ELSE _mode END=ANY(sc.allowed_methods)) THEN RAISE EXCEPTION ''This clock method is not enabled by your administrator''; END IF; IF sc.site_id IS NOT NULL THEN'); EXECUTE definition; END $$;